fn frame(t: i32) {
    host::display::clear(0x0d0e12);
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    let mut click: i32 = 0;
    if down == 1 && prev == 0 {
        click = 1;
    }
    let phase: i32 = host::display::state_get(1);
    let len: i32 = host::display::state_get(3);

    if phase == 0 {
        host::display::draw_string(180, 40, "SET A PIN", 0xffffff, 2);
    } else if phase == 1 {
        host::display::draw_string(176, 40, "ENTER PIN", 0xffffff, 2);
    } else {
        host::display::draw_string(170, 40, "UNLOCKED", 0x33ff88, 2);
    }

    if phase == 2 {
        host::display::fill_rect(60, 130, 392, 60, 0x152a1a);
        host::display::draw_string(120, 150, "THE VAULT IS OPEN", 0x99ffbb, 2);
        host::display::fill_rect(186, 260, 140, 60, 0xdddddd);
        host::display::draw_string(220, 280, "LOCK", 0x000000, 2);
        if click == 1 {
            let px: i32 = host::display::pointer_x();
            let py: i32 = host::display::pointer_y();
            if px >= 186 && px < 326 && py >= 260 && py < 320 {
                host::display::state_set(1, 1);
                host::display::state_set(2, 0);
                host::display::state_set(3, 0);
            }
        }
    } else {
        let mut i: i32 = 0;
        while i < len {
            host::display::draw_char(200 + i * 30, 90, 42, 0xffffff, 3);
            i = i + 1;
        }
        let flash: i32 = host::display::state_get(5);
        if flash > 0 {
            host::display::fill_rect(0, 0, 512, 6, 0xbb2222);
            host::display::draw_string(320, 460, "WRONG PIN", 0xbb3333, 1);
            host::display::state_set(5, flash - 1);
        }
        host::display::draw_string(60, 460, "FAILS", 0x556677, 1);
        host::display::draw_number(110, 458, host::display::state_get(6), 0xffffff, 1);

        let mut k: i32 = 0;
        while k < 12 {
            let kx: i32 = 166 + (k % 3) * 62;
            let ky: i32 = 150 + (k / 3) * 62;
            host::display::fill_rect(kx, ky, 56, 56, 0x1f242e);
            if k < 9 {
                host::display::draw_number(kx + 24, ky + 20, k + 1, 0xffffff, 2);
            } else if k == 9 {
                host::display::draw_char(kx + 24, ky + 20, 67, 0xbb5533, 2);
            } else if k == 10 {
                host::display::draw_number(kx + 24, ky + 20, 0, 0xffffff, 2);
            } else {
                host::display::draw_char(kx + 24, ky + 20, 62, 0x33ff88, 2);
            }
            k = k + 1;
        }

        if click == 1 {
            let px2: i32 = host::display::pointer_x();
            let py2: i32 = host::display::pointer_y();
            if px2 >= 166 && px2 < 352 && py2 >= 150 && py2 < 398 {
                let kc: i32 = (px2 - 166) / 62;
                let kr: i32 = (py2 - 150) / 62;
                if kc < 3 && kr < 4 {
                    let key: i32 = kr * 3 + kc;
                    let entry: i32 = host::display::state_get(2);
                    if key < 9 && len < 4 {
                        host::display::state_set(2, entry * 10 + key + 1);
                        host::display::state_set(3, len + 1);
                    } else if key == 10 && len < 4 {
                        host::display::state_set(2, entry * 10);
                        host::display::state_set(3, len + 1);
                    } else if key == 9 {
                        host::display::state_set(2, 0);
                        host::display::state_set(3, 0);
                    } else if key == 11 && len == 4 {
                        if phase == 0 {
                            host::display::state_set(4, entry);
                            host::display::state_set(1, 1);
                        } else if entry == host::display::state_get(4) {
                            host::display::state_set(1, 2);
                        } else {
                            host::display::state_set(6, host::display::state_get(6) + 1);
                            host::display::state_set(5, 24);
                        }
                        host::display::state_set(2, 0);
                        host::display::state_set(3, 0);
                    }
                }
            }
        }
    }
    host::display::present();
}
